from html.parser import HTMLParser
import sys

class HTMLValidator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.tag_stack = []
        self.void_elements = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
        self.section_count = 0
        self.chart_count = 0
        self.has_title = False
        self.has_toc = False

    def handle_starttag(self, tag, attrs):
        if tag in self.void_elements:
            return
        self.tag_stack.append(tag)
        if tag == 'img':
            self.chart_count += 1
        attrs_dict = dict(attrs)
        if tag == 'div' and attrs_dict.get('id'):
            self.section_count += 1

    def handle_endtag(self, tag):
        if tag in self.void_elements:
            return
        if self.tag_stack and self.tag_stack[-1] == tag:
            self.tag_stack.pop()
        elif tag in self.tag_stack:
            # Try to recover
            while self.tag_stack and self.tag_stack[-1] != tag:
                self.tag_stack.pop()
            if self.tag_stack:
                self.tag_stack.pop()

with open('/app/output/final_report.html', 'r') as f:
    content = f.read()

validator = HTMLValidator()
try:
    validator.feed(content)
    print(f'HTML parsing: OK')
    print(f'Sections with IDs: {validator.section_count}')
    print(f'Charts (img tags): {validator.chart_count}')
    print(f'File size: {len(content):,} bytes')
    print(f'Contains base64 images: {\"data:image/png;base64\" in content}')

    # Check for required sections
    required = ['executive-overview', 'automation-risk-landscape', 'salary-trends', 'skills-demand-analysis', 'job-survival-outlook', 'strategic-recommendations']
    for s in required:
        if f'id=\"{s}\"' in content:
            print(f'  Section found: {s}')
        else:
            print(f'  MISSING section: {s}')
except Exception as e:
    print(f'HTML parsing error: {e}')
"

